/**
 * A local, persisted mirror of the durable XEP-0330 follow list.
 * The source of truth for whom the user follows. Registered as `_converse.state.following`.
 *
 * Consulted by {@link _converse.api.microblog.isFollowing}, so "do we follow this
 * author" is decoupled from "do we happen to have a feed loaded for them" (a
 * browse-only profile feed exists without a follow). Kept in sync two ways:
 * {@link Following#track}/{@link Following#untrack} on this device's own
 * follow/unfollow, and {@link Following#reconcile}, which reconciles the whole
 * mirror against the server list read on `initFollowing` (catching
 * follows/unfollows made on another device or client, e.g. Movim).
 *
 * Mirrors the {@link import('./feeds.js').default} persistence pattern.
 * @extends {Collection<FollowedFeed>}
 */
class Following extends Collection {
    get model() {
        return FollowedFeed;
    }

    get autoSync() {
        return true;
    }

    initialize() {
        const bare_jid = shared_converse.session.get('bare_jid');
        this.storage = createStore(`converse.microblog-following-${bare_jid}`);
    }

    /**
     * The canonical entry id for a follow: `server/node`, matching a feed's id.
     * @param {string} server
     * @param {string} node
     * @returns {string}
     */
    static getId(server, node) {
        return `${server}/${node}`;
    }

    /**
     * Whether the given node is in the follow list.
     * @param {string} server
     * @param {string} [node=MICROBLOG_NODE]
     * @returns {boolean}
     */
    isFollowing(server, node = MICROBLOG_NODE) {
        return !!this.get(Following.getId(server, node));
    }

    /**
     * Record (add or update the title of) a follow.
     * @param {{ server: string, node?: string, title?: string }} attrs
     * @returns {FollowedFeed|Promise<FollowedFeed|void>}
     */
    track({ server, node = MICROBLOG_NODE, title }) {
        const id = Following.getId(server, node);
        const entry = this.get(id);
        if (entry) {
            if (title !== undefined && title !== entry.get('title')) entry.save({ title });
            return entry;
        }
        return this.create({ id, server, node, title });
    }

    /**
     * Drop a follow from the mirror.
     * @param {string} server
     * @param {string} [node=MICROBLOG_NODE]
     */
    untrack(server, node = MICROBLOG_NODE) {
        this.get(Following.getId(server, node))?.destroy();
    }

    /**
     * Reconcile the mirror against the authoritative XEP-0330 list read from the
     * server: upsert every entry present and drop any local entry no longer in the list.
     * @param {Array<{ server: string, node: string, title?: string }>} entries
     * @returns {Promise<void>}
     */
    async reconcile(entries) {
        await this.hydrated;
        const seen = new Set();
        for (const entry of entries) {
            this.track(entry);
            seen.add(Following.getId(entry.server, entry.node));
        }
        for (const model of [...this.models]) {
            if (!seen.has(model.id)) model.destroy();
        }
    }
}

/* export default */ const microblog_following = (Following);

;// CONCATENATED MODULE: ./src/headless/plugins/microblog/utils/following.js







const { stx: following_stx } = api_public.env;

/**
 * Compute the XEP-0330 item id for a subscription: the lowercase-hex SHA-1 of
 * `server + '<' + node + '<' + own-bare-jid`.
 * @param {string} server - The followed entity's pubsub service.
 * @param {string} node - The followed node.
 * @param {string} jid - The follower's bare JID.
 * @returns {Promise<string>}
 */
async function computeFollowItemId(server, node, jid) {
    const ab = await crypto.subtle.digest('SHA-1', stringToArrayBuffer(`${server}<${node}<${jid}`));
    return arrayBufferToHex(ab);
}

/**
 * Build a XEP-0330 follow-list `<item>`.
 * @param {{ server: string, node: string, id: string, title?: string }} attrs
 * @returns {import('strophe.js').Stanza}
 */
function buildFollowItem({ server, node, id, title }) {
    return following_stx`
        <item id="${id}">
            <subscription xmlns="${NS_SUBSCRIPTION}" server="${server}" node="${node}"
                >${title ? following_stx`<title>${title}</title>` : ''}</subscription>
        </item>`;
}

/**
 * Parse a XEP-0330 follow-list `<item>` into a plain object.
 * @param {Element} item
 * @returns {{ server: string, node: string, title?: string }|null}
 */
function parseFollowItem(item) {
    const sub = sizzle(`> subscription[xmlns="${NS_SUBSCRIPTION}"]`, item).pop();
    if (!sub) return null;
    return {
        server: sub.getAttribute('server'),
        node: sub.getAttribute('node'),
        title: sizzle('> title', sub).pop()?.textContent?.trim() || undefined,
    };
}

/**
 * Publish (add or update) a follow to the durable XEP-0330 list on our own PEP
 * service.
 * @param {string} server - The followed entity's pubsub service (a contact's bare JID for PEP).
 * @param {string} node - The followed node (e.g. `urn:xmpp:microblog:0`).
 * @param {string} [title] - A human-readable label.
 * @returns {Promise<void>}
 */
async function publishFollow(server, node, title) {
    const bare_jid = shared_converse.session.get('bare_jid');
    const id = await computeFollowItemId(server, node, bare_jid);
    await shared_api.pubsub.publish(
        null,
        FOLLOWING_NODE,
        buildFollowItem({ server, node, id, title }),
        FOLLOWING_PUBLISH_OPTIONS,
    );
}

/**
 * Retract a follow from the XEP-0330 list.
 * @param {string} server
 * @param {string} node
 * @returns {Promise<void>}
 */
async function retractFollow(server, node) {
    const bare_jid = shared_converse.session.get('bare_jid');
    const id = await computeFollowItemId(server, node, bare_jid);
    await shared_api.pubsub.retract(null, FOLLOWING_NODE, id);
}

/**
 * Read a durable XEP-0330 follow list. Defaults to our own PEP service; pass a
 * JID to read a contact's list instead (their node is `access_model=presence`,
 * so this succeeds for contacts with presence access and is refused otherwise).
 * @param {string} [jid=null] - Whose list to read; null/own for our own.
 * @returns {Promise<Array<{ server: string, node: string, title?: string }>>}
 */
async function readFollowing(jid = null) {
    const { items } = await shared_api.pubsub.items.get(jid, FOLLOWING_NODE);
    const parsed = items.map(parseFollowItem).filter(Boolean);
    // A follow is identified by its (server, node) pair (that's what the XEP-0330
    // item id hashes). Collapse duplicate items for the same pair, which a client
    // can accumulate by re-following a feed over time, so each appears once.
    const seen = new Set();
    return parsed.filter((f) => {
        const key = `${f.server} ${f.node}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

